import React, { useState } from 'react';
import './VerifierPin.css';

function VerifierPin({ utilisateur, onSuccess, onCancel, titre }) {
  const [pin, setPin] = useState('');
  const [message, setMessage] = useState('');
  const [chargement, setChargement] = useState(false);
  const [tentatives, setTentatives] = useState(0);

  const handleVerifier = async () => {
    if (!/^\d{4}$/.test(pin)) {
      setMessage('❌ Entrez un code PIN de 4 chiffres !');
      return;
    }

    setChargement(true);
    setMessage('');

    try {
      const reponse = await fetch('/api/auth/verifier-pin', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          utilisateur_id: utilisateur.id,
          pin
        })
      });

      const donnees = await reponse.json();

      if (reponse.ok) {
        onSuccess();
      } else {
        const nouvellesTentatives = tentatives + 1;
        setTentatives(nouvellesTentatives);
        if (nouvellesTentatives >= 3) {
          setMessage('❌ Trop de tentatives incorrectes. Réessayez plus tard.');
        } else {
          setMessage(`❌ PIN incorrect ! ${3 - nouvellesTentatives} tentative(s) restante(s).`);
        }
        setPin('');
      }
    } catch (erreur) {
      setMessage('❌ Impossible de contacter le serveur');
    }

    setChargement(false);
  };

  return (
    <div className="pin-overlay">
      <div className="pin-modal">
        <h2 className="pin-titre">🔒 {titre || 'Vérification PIN'}</h2>
        <p className="pin-sous-titre">Entrez votre code PIN à 4 chiffres pour continuer</p>

        {message && <div className="pin-message">{message}</div>}

        <div className="pin-champ">
          <input
            type="password"
            placeholder="••••"
            maxLength={4}
            value={pin}
            onChange={(e) => setPin(e.target.value)}
            className="pin-input-modal"
            disabled={tentatives >= 3}
            onKeyPress={(e) => e.key === 'Enter' && handleVerifier()}
          />
        </div>

        <button
          className="pin-btn"
          onClick={handleVerifier}
          disabled={chargement || tentatives >= 3}
        >
          {chargement ? 'Vérification...' : 'Confirmer'}
        </button>

        <button className="pin-btn-annuler" onClick={onCancel}>
          Annuler
        </button>
      </div>
    </div>
  );
}

export default VerifierPin;
